triples = [
    ("Falcon Cloud", "supplies", "Acme Corp"),
    ("Acme Corp", "produces", "Widget X"),
    ("Falcon Cloud", "headquartered_in", "Boston"),
]

def build_graph(triples):
    # build an adjacency list from the triples
    graph = {}
    for subject, relationship, obj in triples:
        graph.setdefault(subject, []).append((relationship, obj))
    return graph

def query_relationship(graph, entity, relationship):
    # look up a specific relationship for an entity
    return [obj for rel, obj in graph.get(entity, []) if rel == relationship]

graph = build_graph(triples)
print("Knowledge graph built from triples:")
for entity, edges in graph.items():
    print(f"  {entity}: {edges}")

result = query_relationship(graph, "Falcon Cloud", "supplies")
print(f"\nWho does Falcon Cloud supply? {result}")
